}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-3 text-sm text-foreground outline-none hover:bg-muted focus:bg-muted selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ring",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </AriaListBoxItem>
  );
}

export function SelectionMark({
  isSelected,
  className,
}: {
  isSelected: boolean;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      className={cn("ms-auto shrink-0", className)}
      initial={false}
      animate={{ opacity: isSelected ? 1 : 0, scale: isSelected ? 1 : 0.85 }}
      transition={{ duration: reduceMotion ? 0 : duration.fast, ease: easeOut }}
    >
      <CheckIcon size={16} weight="bold" />
    </motion.span>
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { duration, easeOut, edgeOffset } from "./motion";
import { cn } from "./utils";

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { opacity: 0, ...edgeOffset(placement, 5), scale: 0.98 }
            }
            animate={
              isExiting
                ? {
                    opacity: 0,
                    ...(reduceMotion ? {} : edgeOffset(placement, 5)),
                    scale: reduceMotion ? 1 : 0.99,
                  }
                : { opacity: 1, x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: reduceMotion
                ? 0
                : isExiting
                  ? duration.fast
                  : duration.base,
              ease: easeOut,
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-5 text-popover-foreground [overflow-wrap:anywhere] shadow-[var(--shadow-float)] outline-none data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import { CaretRightIcon } from "@phosphor-icons/react";
import { useSyncExternalStore } from "react";
import {
  Menu as AriaMenu,
  MenuItem as AriaMenuItem,
  composeRenderProps,
  type MenuItemProps,
  type MenuProps,
  MenuTrigger,
  PopoverContext,
  Separator,
  type SeparatorProps,
  SubmenuTrigger,
  useSlottedContext,
} from "react-aria-components";
import { cn } from "./utils";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";

export { MenuTrigger, SubmenuTrigger };

const narrowQuery = "(max-width: 639px)";

function subscribeToNarrow(onChange: () => void) {
  const media = window.matchMedia(narrowQuery);
  media.addEventListener("change", onChange);
  return () => media.removeEventListener("change", onChange);
}

function isNarrowViewport() {
  return window.matchMedia(narrowQuery).matches;
}

export function Menu<T extends object>({ className, ...props }: MenuProps<T>) {
  return (
    <MenuPopover>
      <MenuContent {...props} className={className} />
    </MenuPopover>
  );
}

export function MenuPopover({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  const context = useSlottedContext(PopoverContext, props.slot);
  const isSubmenu = context?.trigger === "SubmenuTrigger";
  const isNarrow = useSyncExternalStore(
    subscribeToNarrow,
    isNarrowViewport,
    () => false,
  );
  const stacked = isSubmenu && isNarrow;
  return (
    <Popover
      {...props}
      data-slot="menu-popover"
      placement={props.placement ?? (stacked ? "bottom end" : undefined)}
      offset={
        props.offset ?? context?.offset ?? (isSubmenu ? (stacked ? 4 : -2) : 7)
      }
      crossOffset={
        props.crossOffset ?? (isSubmenu && !stacked ? -6 : undefined)
      }
      maxHeight={props.maxHeight ?? 300}
      className={composeRenderProps(className, (className) =>
        cn(
          "min-w-[min(11rem,calc(100vw-2rem))] rounded-lg border-0 p-1.5 ring-1 ring-border/70",
          className,
        ),
      )}
    >
      {children}
    </Popover>
  );
}

export function MenuContent<T extends object>({
  className,
  ...props
}: MenuProps<T>) {
  return (
    <AriaMenu
      {...props}
      data-slot="menu-content"
      className={composeRenderProps(className, (className) =>
        cn("grid gap-1 outline-none", className),
      )}
    />
  );
}

export function MenuItem<T extends object>({
  className,
  children,
  ...props
}: MenuItemProps<T>) {
  return (
    <AriaMenuItem
      {...props}
      data-slot="menu-item"
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-11 cursor-pointer items-center gap-2.5 rounded-md px-3 py-2 text-sm text-foreground outline-none hover:bg-muted focus:bg-muted open:bg-muted focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-ring selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&>[data-slot=kbd]]:ms-auto",
          className,
        ),
      )}
    >
      {composeRenderProps(
        children,
        (content, { isSelected, selectionMode, hasSubmenu }) => (
          <>
            {content}
            {selectionMode !== "none" && !hasSubmenu && (
              <SelectionMark isSelected={isSelected} />
            )}
            {hasSubmenu && (
              <CaretRightIcon
                size={16}
                aria-hidden="true"
                className="ms-auto text-muted-foreground rtl:rotate-180"
              />
            )}
          </>
        ),
      )}
    </AriaMenuItem>
  );
}

export function MenuSeparator({ className, ...props }: SeparatorProps) {
  return (
    <Separator
      {...props}
      data-slot="menu-separator"
      className={cn("border-t border-border/70", className)}
    />
  );
}

export const fieldLabelStyles = "text-sm font-medium text-foreground";
export const fieldDescriptionStyles = "text-xs leading-5 text-muted-foreground";
export const fieldErrorStyles = "text-xs leading-5 text-destructive";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] placeholder:text-muted-foreground/80 hover:border-primary/45 focus:border-ring focus:ring-3 focus:ring-ring/50 invalid:border-destructive invalid:ring-3 invalid:ring-destructive/20 invalid:hover:border-destructive invalid:focus:border-destructive invalid:focus:ring-destructive/30 [&[readonly]]:bg-muted/40 [&[readonly]]:hover:border-input disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-60 disabled:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { Button, type ButtonProps } from "react-aria-components";

export function PressButton({ isDisabled, ...props }: ButtonProps) {
  const reduceMotion = useReducedMotion();

  return (
    <Button
      data-slot="press-button"
      {...props}
      isDisabled={isDisabled}
      render={
        props.render ??
        ((domProps) => (
          <motion.button
            {...(domProps as HTMLMotionProps<"button">)}
            whileTap={reduceMotion || isDisabled ? undefined : { scale: 0.96 }}
            transition={{ type: "spring", stiffness: 500, damping: 36 }}
          />
        ))
      }
    />
  );
}

"use client";

import { CaretDownIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useContext } from "react";
import {
  type Button as AriaButton,
  Select as AriaSelect,
  type SelectProps as AriaSelectProps,
  SelectValue as AriaSelectValue,
  composeRenderProps,
  FieldError,
  Label,
  ListBox,
  ListBoxItem,
  SelectStateContext,
  Text,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldLabelStyles,
} from "./field-styles";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";
import { PressButton } from "./press-button";

const selectTriggerStyles =
  "relative flex min-h-12 w-full min-w-0 cursor-pointer items-center rounded-lg border border-input bg-card ps-3.5 pe-10 text-start text-base leading-6 text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-visible:border-destructive group-invalid:focus-visible:ring-destructive/30 disabled:cursor-default disabled:bg-muted disabled:opacity-60 sm:text-sm sm:leading-5";
const selectValueStyles =
  "min-w-0 flex-1 self-center truncate text-start data-[placeholder]:text-muted-foreground";
const selectItemStyles =
  "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none hover:bg-muted focus:bg-muted selected:bg-accent selected:text-accent-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";
const selectPopoverStyles =
  "w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70";

export interface SelectOption {
  id: string;
  name: string;
  description?: string;
}
export interface SelectProps
  extends Omit<AriaSelectProps<SelectOption>, "children" | "className"> {
  label?: string;
  description?: string;
  options?: SelectOption[];
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaSelectProps<SelectOption>["className"];
  children?: AriaSelectProps<SelectOption>["children"];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export function Select({
  label,
  description,
  options,
  className,
  children,
  value,
  defaultValue,
  onValueChange,
  placeholder = "Select an option",
  ...props
}: SelectProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaSelect
      {...props}
      data-slot="select"
      selectedKey={value ?? props.selectedKey}
      defaultSelectedKey={defaultValue ?? props.defaultSelectedKey}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(key === null ? "" : String(key));
      }}
      placeholder={placeholder}
      className={composeRenderProps(className, (className) =>
        cn("group flex w-full min-w-0 flex-col gap-2", className),
      )}
    >
      {children ??
        (({ isOpen }) => (
          <>
            {label && (
              <Label data-slot="select-label" className={fieldLabelStyles}>
                {label}
              </Label>
            )}
            <PressButton
              data-slot="select-trigger"
              className={selectTriggerStyles}
            >
              <AriaSelectValue
                data-slot="select-value"
                className={selectValueStyles}
              >
                {({ selectedText, isPlaceholder, state }) =>
                  isPlaceholder
                    ? placeholder
                    : (options?.find(
                        (option) => option.id === state.selectedKey,
                      )?.name ?? selectedText)
                }
              </AriaSelectValue>
              <SelectChevron open={isOpen} reduceMotion={reduceMotion} />
            </PressButton>
            {description && (
              <Text
                slot="description"
                data-slot="select-description"
                className={fieldDescriptionStyles}
              >
                {description}
              </Text>
            )}
            <SelectError />
            <Popover
              data-slot="select-content"
              placement="bottom start"
              offset={7}
              maxHeight={268}
              className={selectPopoverStyles}
            >
              <ListBox
                data-slot="select-list-box"
                items={options ?? []}
                className="grid gap-1 outline-none"
              >
                {(option) => (
                  <ListBoxItem
                    data-slot="select-item"
                    id={option.id}
                    textValue={option.name}
                    className={selectItemStyles}
                  >
                    {({ isSelected }) => (
                      <>
                        <span className="min-w-0">
                          <span className="block font-medium">
                            {option.name}
                          </span>
                          {option.description && (
                            <span className="mt-0.5 block text-xs text-muted-foreground group-selected/item:text-accent-foreground">
                              {option.description}
                            </span>
                          )}
                        </span>
                        <SelectionMark isSelected={isSelected} />
                      </>
                    )}
                  </ListBoxItem>
                )}
              </ListBox>
            </Popover>
          </>
        ))}
    </AriaSelect>
  );
}

export function SelectLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="select-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function SelectTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <PressButton
      {...props}
      data-slot="select-trigger"
      className={composeRenderProps(className, (className) =>
        cn(selectTriggerStyles, className),
      )}
    >
      {children ?? (
        <>
          <SelectValue />
          <SelectChevron />
        </>
      )}
    </PressButton>
  );
}

function SelectChevron({
  open,
  reduceMotion,
}: {
  open?: boolean;
  reduceMotion?: boolean | null;
}) {
  const contextOpen = useContext(SelectStateContext)?.isOpen;
  const prefersReducedMotion = useReducedMotion();
  const isOpen = open ?? contextOpen;
  const reduce = reduceMotion ?? prefersReducedMotion;
  return (
    <span
      aria-hidden="true"
      data-slot="select-chevron"
      className="pointer-events-none absolute inset-y-0 end-3.5 grid place-items-center text-muted-foreground"
    >
      <motion.span
        className="grid size-4 place-items-center"
        initial={false}
        animate={{ rotate: isOpen ? 180 : 0 }}
        transition={{ duration: reduce ? 0 : duration.base, ease: easeOut }}
      >
        <CaretDownIcon size={16} />
      </motion.span>
    </span>
  );
}

export function SelectValue({
  className,
  ...props
}: React.ComponentProps<typeof AriaSelectValue>) {
  return (
    <AriaSelectValue
      {...props}
      data-slot="select-value"
      className={composeRenderProps(className, (className) =>
        cn(selectValueStyles, className),
      )}
    >
      {props.children ??
        (({ isPlaceholder, selectedText, defaultChildren }) =>
          isPlaceholder ? defaultChildren : selectedText || defaultChildren)}
    </AriaSelectValue>
  );
}

export function SelectContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  return (
    <Popover
      {...props}
      data-slot="select-content"
      placement={props.placement ?? "bottom start"}
      offset={props.offset ?? 7}
      maxHeight={props.maxHeight ?? 268}
      className={composeRenderProps(className, (className) =>
        cn(selectPopoverStyles, className),
      )}
    >
      <ListBox data-slot="select-list-box" className="grid gap-1 outline-none">
        {children}
      </ListBox>
    </Popover>
  );
}

export function SelectItem({
  className,
  children,
  textValue,
  ...props
}: Omit<React.ComponentProps<typeof ListBoxItem>, "children"> & {
  children: ReactNode;
}) {
  return (
    <ListBoxItem
      {...props}
      textValue={
        textValue ?? (typeof children === "string" ? children : undefined)
      }
      data-slot="select-item"
      className={composeRenderProps(className, (className) =>
        cn(selectItemStyles, className),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </ListBoxItem>
  );
}

export function SelectError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="select-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}

export function SelectDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="select-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

